<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Plus, Search, Download, Refresh, Box, User, OfficeBuilding } from '@element-plus/icons-vue'
import { api, download, query } from '../api'
import { useApp } from '../store'
import { masterLabels, money } from '../utils'
import DataTable from '../components/DataTable.vue'
const app = useApp(), route = useRoute(), router = useRouter()
const kind = computed(() => String(route.params.kind || 'product')), search = ref(''), state = ref(''), rows = ref<any[]>([]), refs = ref<Record<string, any[]>>({}), busy = ref(false), saving = ref(false), open = ref(false)
const form = reactive<any>({ id: 0, kind: 'product', code: '', name: '', data: {}, active: true })
const editable = computed(() => app.can('base.edit') && app.writable('base'))
async function load() { busy.value = true; try { const result = await api('/masters/' + kind.value + '?' + query({ search: search.value })); rows.value = result.items } catch {} finally { busy.value = false } }
async function loadRefs() { const pairs = await Promise.all(['category', 'brand', 'warehouse', 'unit', 'employee', 'organization'].map(async k => [k, (await api('/masters/' + k + '?active=true')).items])); refs.value = Object.fromEntries(pairs) }
watch(() => [route.params.kind, route.query.search], () => { search.value = String(route.query.search || ''); state.value = ''; load() }); watch(() => app.tick, load)
onMounted(() => { search.value = String(route.query.search || ''); load(); loadRefs().catch(() => {}) })
const displayRows = computed(() => rows.value.filter(r => state.value === '' || String(Number(r.active)) === state.value).map(r => ({ ...r, ...r.data, active: r.active })))
const columns = computed(() => {
  const cols: any[] = [{ key: 'code', label: '编码', minWidth: 115 }, { key: 'name', label: kind.value === 'product' ? '商品名称' : '名称', minWidth: 180 }]
  if (kind.value === 'product') cols.push({ key: 'spec', label: '规格型号', minWidth: 110 }, { key: 'unit', label: '单位', width: 70 }, { key: 'sales_price', label: '销售价', type: 'money', hidden: !app.amountVisible }, { key: 'purchase_price', label: '参考采购价', type: 'money', hidden: !app.costVisible }, { key: 'min_stock', label: '库存下限', type: 'qty' })
  else if (['customer', 'supplier', 'employee'].includes(kind.value)) cols.push({ key: 'contact', label: '联系人', width: 110 }, { key: 'phone', label: '联系电话', minWidth: 140 }, ...(kind.value === 'customer' ? [{ key: 'level', label: '客户等级', width: 90 }, { key: 'credit_limit', label: '信用额度', type: 'money', hidden: !app.amountVisible }] : []), { key: 'address', label: '地址', minWidth: 180 })
  else if (['warehouse', 'location'].includes(kind.value)) cols.push({ key: 'manager', label: '负责人', width: 110 }, { key: 'address', label: '地址 / 说明', minWidth: 180 })
  else cols.push({ key: 'remark', label: '说明', minWidth: 200 })
  cols.push({ key: 'active', label: '状态', type: 'boolean', width: 85 }); return cols
})
function edit(row?: any) { const source = row ? rows.value.find(r => r.id === row.id) : null; Object.assign(form, source ? JSON.parse(JSON.stringify(source)) : { id: 0, kind: kind.value, code: '', name: '', active: true, data: { unit: '件', purchase_price: '0', sales_price: '0', retail_price: '0', guide_price: '0', min_price: '0', min_stock: '0', max_stock: '0', credit_limit: '0', term_days: 30, discount_bps: 10000, level: '普通客户', batch_tracking: false, serial_tracking: false, consignment: false } }); open.value = true; loadRefs().catch(() => {}) }
async function save() { if (!form.name.trim()) { ElMessage.warning('请填写名称'); return }; saving.value = true; try { await api('/masters/' + kind.value + (form.id ? '/' + form.id : ''), form.id ? 'PUT' : 'POST', form); open.value = false; ElMessage.success('基础资料已保存'); app.changed(); loadRefs().catch(() => {}) } catch {} finally { saving.value = false } }
function exportRows() { download('/export?' + query({ type: 'masters', kind: kind.value, search: search.value })) }
</script>
<template>
  <div class="page-head"><div><h1>基础资料</h1><p>统一维护商品、往来单位与仓库，让每一笔业务有准确的起点。</p></div><div class="page-actions"><el-button :icon="Download" @click="exportRows">导出资料</el-button><el-button v-if="app.can('base.edit')" type="primary" :icon="Plus" :disabled="!editable" @click="edit()">新增{{ masterLabels[kind]?.replace('档案', '').replace('管理', '') }}</el-button></div></div>
  <section class="panel"><div class="subnav"><button v-for="(label, key) in masterLabels" :key="key" :class="{ selected: key === kind }" @click="router.push('/masters/' + key)">{{ label }}</button></div><div class="filter-row"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索名称、编码、联系人…" clearable @keyup.enter="load" @clear="load"/><el-select v-model="state" placeholder="全部状态" clearable><el-option label="启用" value="1"/><el-option label="停用" value="0"/></el-select><el-button type="primary" plain @click="load">查询</el-button><div class="spacer"></div><span class="muted">{{ masterLabels[kind] }} · {{ displayRows.length }} 条</span></div><DataTable :rows="displayRows" :columns="columns" :loading="busy" empty="还没有基础资料，点击右上角新增" @row="edit"><template #actions="{ row }"><el-button link type="primary" @click="edit(row)">{{ editable ? '编辑资料' : '查看资料' }}</el-button></template></DataTable></section>
  <el-drawer v-model="open" :title="(form.id ? '编辑' : '新增') + masterLabels[kind]" size="680px" destroy-on-close><el-form label-position="top" :disabled="!editable"><div class="form-grid two"><el-form-item label="编码"><el-input v-model="form.code" placeholder="留空自动生成" maxlength="64"/></el-form-item><el-form-item :label="kind === 'product' ? '商品名称 *' : '名称 *'"><el-input v-model="form.name" placeholder="请输入名称" maxlength="80"/></el-form-item>
    <template v-if="kind === 'product'"><el-form-item label="商品分类"><el-select v-model="form.data.category_id" clearable filterable><el-option v-for="r in refs.category" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="品牌"><el-select v-model="form.data.brand_id" clearable filterable><el-option v-for="r in refs.brand" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="规格型号"><el-input v-model="form.data.spec" placeholder="如：标准款 / 500ml"/></el-form-item><el-form-item label="计量单位"><el-select v-model="form.data.unit" filterable allow-create default-first-option><el-option v-for="r in refs.unit" :key="r.id" :value="r.name" :label="r.name"/></el-select></el-form-item><el-form-item label="商品条码"><el-input v-model="form.data.barcode"/></el-form-item><el-form-item v-if="app.costVisible" label="参考采购价"><el-input v-model="form.data.purchase_price" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item><template v-if="app.amountVisible"><el-form-item v-for="field in [{ key:'sales_price', name:'基础销售价' },{ key:'retail_price', name:'零售价' },{ key:'guide_price', name:'商品指导价' },{ key:'min_price', name:'最低售价' }]" :key="field.key" :label="field.name"><el-input v-model="form.data[field.key]" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item></template><el-form-item label="库存下限"><el-input v-model="form.data.min_stock" inputmode="decimal"/></el-form-item><el-form-item label="库存上限（0 不限制）"><el-input v-model="form.data.max_stock" inputmode="decimal"/></el-form-item><div class="wide flex gap12 mb16"><el-checkbox v-model="form.data.batch_tracking">按批次管理</el-checkbox><el-checkbox v-model="form.data.serial_tracking">按序列号管理</el-checkbox></div><div class="hint-box wide mb16">启用批次 / 序列号后，出入库必须填写对应信息。产生库存流水后，单位与追踪方式不能修改。</div></template>
    <template v-if="['customer','supplier','employee'].includes(kind)"><el-form-item label="联系人"><el-input v-model="form.data.contact"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.data.phone"/></el-form-item><el-form-item class="wide" label="联系地址"><el-input v-model="form.data.address"/></el-form-item><el-form-item label="电子邮箱"><el-input v-model="form.data.email"/></el-form-item></template>
    <template v-if="kind === 'customer' || kind === 'supplier'"><el-form-item label="账期（天）"><el-input-number v-model="form.data.term_days" :min="0" :max="3650" :precision="0" controls-position="right"/></el-form-item><el-form-item v-if="app.amountVisible" label="信用额度（0 不限制）"><el-input v-model="form.data.credit_limit" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item><el-form-item label="开户银行"><el-input v-model="form.data.bank_name"/></el-form-item><el-form-item label="银行账号"><el-input v-model="form.data.bank_account"/></el-form-item><el-form-item label="税号"><el-input v-model="form.data.tax_id"/></el-form-item></template>
    <template v-if="kind === 'customer'"><el-form-item label="客户等级"><el-select v-model="form.data.level" filterable allow-create default-first-option><el-option v-for="l in ['普通客户','银牌客户','金牌客户','VIP客户']" :key="l" :label="l" :value="l"/></el-select></el-form-item><el-form-item v-if="app.amountVisible" label="基础价折扣（10000 原价，9500 为95折）"><el-input-number v-model="form.data.discount_bps" :min="0" :max="10000" :precision="0" controls-position="right"/></el-form-item><el-form-item label="负责业务员"><el-select v-model="form.data.employee_id" clearable filterable><el-option v-for="r in refs.employee" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item></template>
    <template v-if="kind === 'warehouse' || kind === 'location'"><el-form-item v-if="kind === 'location'" label="所属仓库 *"><el-select v-model="form.data.warehouse_id" filterable><el-option v-for="r in refs.warehouse" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="负责人"><el-input v-model="form.data.manager"/></el-form-item><el-form-item class="wide" label="地址 / 说明"><el-input v-model="form.data.address"/></el-form-item><el-form-item v-if="kind === 'warehouse'" label="仓库用途"><el-checkbox v-model="form.data.consignment">委托代销仓库</el-checkbox></el-form-item></template>
    <el-form-item v-if="kind === 'category'" label="上级分类"><el-select v-model="form.data.parent_id" clearable filterable><el-option v-for="r in refs.category?.filter(v => v.id !== form.id)" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item>
    <el-form-item v-if="kind === 'employee'" label="所属组织"><el-select v-model="form.data.organization_id" clearable><el-option v-for="r in refs.organization" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item>
    <template v-if="kind === 'dictionary'"><el-form-item label="字典分组"><el-input v-model="form.data.group" placeholder="如：结算方式"/></el-form-item><el-form-item label="字典值"><el-input v-model="form.data.value"/></el-form-item></template><el-form-item class="wide" label="备注"><el-input v-model="form.data.remark" type="textarea" :rows="3" maxlength="1000"/></el-form-item><el-form-item label="资料状态"><el-switch v-model="form.active" active-text="启用" inactive-text="停用"/></el-form-item>
  </div></el-form><template #footer><el-button @click="open = false">取消</el-button><el-button v-if="editable" type="primary" :loading="saving" @click="save">保存资料</el-button></template></el-drawer>
</template>
